    require(all(canonical(support[k])==canonical(expected[k]) for k in ('source_ref','accepted_header_ref')) and support['accepted_at_utc']==expected['accepted_at_utc'] and all(support.get(k,expected[k])==expected[k] for k in ('accession','form')),'DECLARED_HEADER_SOURCE_VERSION_PAIR_CHANGED')
    hp=_pin(expected['original_header_prefix_custody_ref'])
    with hp.open('rb') as f:prefix=f.read(min(65536,hp.stat().st_size))
    header_path=_pin(support['accepted_header_ref']);require(header_path.stat().st_size<=8192,'DECLARED_HEADER_METADATA_ONLY_REQUIRED');header=header_path.read_bytes();require(0<len(header) and prefix[:len(header)]==header,'DECLARED_HEADER_NOT_ORIGINAL_SUBMISSION_PREFIX')
    require(re.search(rb'ACCESSION NUMBER:\s*'+re.escape(expected['accession'].encode())+rb'\s*(?:\r?\n)',header) is not None and re.search(rb'CONFORMED SUBMISSION TYPE:\s*'+re.escape(expected['form'].encode())+rb'\s*(?:\r?\n)',header) is not None,'DECLARED_ACTUAL_ACCESSION_FORM_REQUIRED')
    if canonical(expected['original_header_prefix_custody_ref'])!=canonical(support['source_ref']):
        member=re.search(rb'<DOCUMENT>\s*<TYPE>([^\r\n]+)\s*<SEQUENCE>[^\r\n]+\s*<FILENAME>([^\r\n]+).*?<TEXT>\r?\n',prefix,re.S)
        require(member is not None and member.group(1).decode().strip()==expected['form'] and member.group(2).decode().strip()==Path(support['source_ref']['path']).name,'DECLARED_ORIGINAL_PRIMARY_MEMBER_ROLE_REQUIRED')
        a=member.end();require(prefix[a:a+7]==b'<XBRL>\n','DECLARED_ORIGINAL_XBRL_WRAPPER_REQUIRED');a+=7
        with _pin(support['source_ref']).open('rb') as f:primary_prefix=f.read(len(prefix)-a)
        require(primary_prefix==prefix[a:],'DECLARED_PRIMARY_NOT_SAME_ORIGINAL_SUBMISSION_PREFIX')
    return header

